sealed class SessionProxy : DispatchProxy {            // DispatchProxy.Create<ISession, SessionProxy>()
    ISession _target = default!;                       // wired by the grantor after Create
    volatile bool _revoked;
    protected override object? Invoke(MethodInfo? m, object?[]? args) {
        if (_revoked) throw new InvalidOperationException("capability revoked");
        return m!.Invoke(_target, args);               // one check point for all members
    }
    public void Revoke() => _revoked = true;           // the grantor keeps this handle
}
